// A pre-rendered brand card avoids runtime font/image generation on Workers.
export const runtime = 'nodejs'
export const dynamic = 'force-static'
export const alt = 'Starlight AI — AI automation studio'
export const size = { width: 1200, height: 630 }
export const contentType = 'image/png'
const image = ''
export default function OpengraphImage() {
  return new Response(Buffer.from(image, 'base64'), { headers: { 'Content-Type': contentType, 'Cache-Control': 'public, max-age=86400' } })
}
